def transform(grid):
    h, w = len(grid), len(grid[0])
    result = [list(row) for row in grid]

    # Find all clusters of 3s
    visited = set()
    clusters = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3 and (r, c) not in visited:
                cluster = []
                queue = [(r, c)]
                while queue:
                    curr_r, curr_c = queue.pop(0)
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    cluster.append((curr_r, curr_c))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3 and (nr, nc) not in visited:
                            queue.append((nr, nc))
                clusters.append(cluster)

    # For each cluster, apply vertical mirror if 3 columns wide
    for cluster in clusters:
        rows = [r for r,c in cluster]
        cols = [c for r,c in cluster]
        min_c, max_c = min(cols), max(cols)
        width = max_c - min_c + 1

        if width == 3:
            for r in rows:
                for c in cols:
                    mirror_c = w - 1 - c
                    result[r][c] = grid[r][mirror_c]

    return result

